from __future__ import annotations

from collections import defaultdict, deque
from typing import Callable


class Runner:
    def __init__(self) -> None:
        self._jobs: dict[str, tuple[list[str], Callable[[], None]]] = {}

    def add(self, job_id: str, deps: list[str], fn: Callable[[], None]) -> None:
        self._jobs[job_id] = (deps, fn)

    def waves(self) -> list[list[str]]:
        return self._compute_waves()

    def run(self) -> dict[str, str]:
        wave_list = self._compute_waves()
        if not wave_list:
            return {}

        statuses: dict[str, str] = {}
        skipped: set[str] = set()
        failed: set[str] = set()
        dependents = self._dependents()

        for wave in wave_list:
            for job_id in wave:
                if job_id in skipped:
                    statuses[job_id] = "skipped"
                    continue

                deps, fn = self._jobs[job_id]
                if any(dep in failed or dep in skipped for dep in deps):
                    statuses[job_id] = "skipped"
                    skipped.add(job_id)
                    self._mark_transitive_dependents(job_id, skipped, dependents)
                    continue

                try:
                    fn()
                except Exception:
                    statuses[job_id] = "failed"
                    failed.add(job_id)
                    self._mark_transitive_dependents(job_id, skipped, dependents)
                else:
                    statuses[job_id] = "ok"

        return statuses

    def _compute_waves(self) -> list[list[str]]:
        if not self._jobs:
            return []

        job_ids = set(self._jobs)
        for job_id, (deps, _) in self._jobs.items():
            for dep in deps:
                if dep not in job_ids:
                    raise ValueError(f"unknown dependency {dep!r}")

        in_degree = {job_id: len(deps) for job_id, (deps, _) in self._jobs.items()}
        dependents: dict[str, list[str]] = defaultdict(list)
        for job_id, (deps, _) in self._jobs.items():
            for dep in deps:
                dependents[dep].append(job_id)

        ready = sorted(job_id for job_id in job_ids if in_degree[job_id] == 0)
        waves: list[list[str]] = []
        placed = 0

        while ready:
            layer = sorted(ready)
            waves.append(layer)
            placed += len(layer)
            next_ready: list[str] = []
            for job_id in layer:
                for child in dependents[job_id]:
                    in_degree[child] -= 1
                    if in_degree[child] == 0:
                        next_ready.append(child)
            ready = next_ready

        if placed != len(job_ids):
            raise ValueError("cycle")

        return waves

    def _dependents(self) -> dict[str, list[str]]:
        dependents: dict[str, list[str]] = defaultdict(list)
        for job_id, (deps, _) in self._jobs.items():
            for dep in deps:
                dependents[dep].append(job_id)
        return dependents

    @staticmethod
    def _mark_transitive_dependents(
        job_id: str,
        skipped: set[str],
        dependents: dict[str, list[str]],
    ) -> None:
        queue: deque[str] = deque([job_id])
        while queue:
            current = queue.popleft()
            for child in dependents.get(current, []):
                if child not in skipped:
                    skipped.add(child)
                    queue.append(child)

