from __future__ import annotations

from datetime import datetime, timedelta, timezone

UTC = timezone.utc


def to_utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=UTC)
    return value.astimezone(UTC)


def _in_missing_dst_hour(naive: datetime, tz: datetime.tzinfo) -> bool:
    start = naive.replace(tzinfo=tz)
    next_hour = (naive + timedelta(hours=1)).replace(tzinfo=tz)
    return next_hour.astimezone(UTC) - start.astimezone(UTC) < timedelta(hours=1)


def _resolve_local(naive: datetime, tz: datetime.tzinfo) -> datetime:
    candidate = naive
    for _ in range(2):
        if not _in_missing_dst_hour(candidate, tz):
            return candidate.replace(tzinfo=tz)
        candidate += timedelta(hours=1)
    return candidate.replace(tzinfo=tz)


class Book:
    def __init__(self) -> None:
        self._slots: list[tuple[datetime, datetime]] = []

    def add(self, start: datetime, end: datetime) -> int:
        utc_start, utc_end = to_utc(start), to_utc(end)
        if utc_end <= utc_start:
            raise ValueError("empty interval")
        if self.conflicts(start, end):
            raise ValueError("overlap")
        self._slots.append((utc_start, utc_end))
        return len(self._slots) - 1

    def add_weekly(self, start: datetime, end: datetime, count: int) -> list[int]:
        ids: list[int] = []
        duration = to_utc(end) - to_utc(start)
        if start.tzinfo is None:
            for index in range(count):
                delta = timedelta(days=7 * index)
                ids.append(self.add(start + delta, end + delta))
            return ids

        tz = start.tzinfo
        for index in range(count):
            target_date = start.date() + timedelta(weeks=index)
            week_start = _resolve_local(
                datetime.combine(target_date, start.time()),
                tz,
            )
            ids.append(self.add(week_start, week_start + duration))
        return ids

    def conflicts(self, start: datetime, end: datetime) -> bool:
        utc_start, utc_end = to_utc(start), to_utc(end)
        for other_start, other_end in self._slots:
            if utc_start <= other_end and utc_end >= other_start:
                return True
        return False

    def slots(self) -> list[tuple[datetime, datetime]]:
        return list(self._slots)

